def transform(grid):
    left = [row[:4] for row in grid]
    right = [row[5:9] for row in grid]
    if all(all(a or b for a, b in zip(lrow, rrow)) for lrow, rrow in zip(left, right)):
        return [[a if a else b for a, b in zip(lrow, rrow)] for lrow, rrow in zip(left, right)]
    return left
